<script setup>
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import WorkspaceLayout from '../components/WorkspaceLayout.vue'
import {auth,setUser} from '../auth'
import {api,errorMessage} from '../workspace-api'
const router=useRouter(),error=ref(''),notice=ref(''),busy=ref(false),oldPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),invites=ref([]),users=ref([]),code=ref(''),days=ref(7),uses=ref(1)
async function refresh(){if(auth.user?.role==='admin'){const [a,b]=await Promise.all([api.get('/auth/invites'),api.get('/auth/users')]);invites.value=a.data;users.value=b.data}}
async function action(task){busy.value=true;error.value='';notice.value='';try{await task()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function changePassword(){if(newPassword.value!==confirmPassword.value){error.value='两次新密码不一致';return}await action(async()=>{await api.post('/auth/password',{oldPassword:oldPassword.value,newPassword:newPassword.value});setUser(null);router.replace('/login?changed=1')})}
async function createInvite(){await action(async()=>{code.value=(await api.post('/auth/invites',{maxUses:uses.value,days:days.value})).data.code;notice.value='邀请码仅在创建时显示，请复制保存。';await refresh()})}
async function revoke(id){await action(async()=>{await api.delete('/auth/invites/'+id);await refresh()})}
async function toggle(user){await action(async()=>{await api.post('/auth/users/'+user.id,{active:!user.active});await refresh()})}
const status=i=>i.revoked?'已撤销':i.expires*1000<Date.now()?'已过期':i.uses>=i.max_uses?'已用完':'可使用'
onMounted(()=>refresh().catch(e=>error.value=errorMessage(e)))
</script>
<template><WorkspaceLayout title="账号管理" description="管理登录密码；管理员可邀请新用户并管理账号状态。"><div v-if="error" class="error" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div><div class="workspace-grid"><aside><section class="panel"><h2>{{auth.user?.username}}</h2><span class="badge">{{auth.user?.role==='admin'?'管理员':'普通用户'}}</span><p class="muted" style="margin-top:16px">上传资料、聊天记忆、方案与 PDF 按账号隔离。内置知识库共享。</p><p v-if="auth.user?.role==='admin'" class="muted">通用终端仅管理员可用。</p></section><section class="panel"><h2>修改密码</h2><form @submit.prevent="changePassword"><label>当前密码<input v-model="oldPassword" type="password" autocomplete="current-password" required maxlength="128" :disabled="busy"></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="10" maxlength="128" :disabled="busy"></label><label>确认新密码<input v-model="confirmPassword" type="password" autocomplete="new-password" required minlength="10" maxlength="128" :disabled="busy"></label><button :disabled="busy">更新密码</button><p class="muted" style="margin-top:12px">至少 10 个字符。更新后所有设备的登录状态都会失效。</p></form></section></aside><div v-if="auth.user?.role==='admin'"><section class="panel"><h2>邀请新用户</h2><form @submit.prevent="createInvite"><div class="split"><label>可用次数<input v-model.number="uses" type="number" min="1" max="20" required :disabled="busy"></label><label>有效天数<input v-model.number="days" type="number" min="1" max="30" required :disabled="busy"></label></div><button :disabled="busy">生成邀请码</button></form><label v-if="code" style="margin-top:20px">本次邀请码（点击选中复制）<input :value="code" readonly @focus="$event.target.select()"></label><p class="muted" style="margin-top:12px">把邀请码与网站地址发给受邀者，对方可在注册页自行设置密码。</p></section><section class="panel"><h2>邀请码记录</h2><article v-for="i in invites" :key="i.id" class="item"><div class="row"><span class="badge">{{status(i)}}</span><p class="muted">已使用 {{i.uses}} / {{i.max_uses}} 次 · {{new Date(i.expires*1000).toLocaleDateString()}} 到期</p><button v-if="status(i)==='可使用'" class="secondary" :disabled="busy" @click="revoke(i.id)">撤销</button></div></article><p v-if="!invites.length" class="muted">尚未创建邀请码</p></section><section class="panel"><h2>用户账号</h2><article v-for="u in users" :key="u.id" class="item"><div class="row"><strong>{{u.username}}</strong><span class="badge" :class="{failed:!u.active}">{{u.role==='admin'?'管理员':u.active?'正常':'已停用'}}</span><button v-if="u.role!=='admin'" class="secondary" :disabled="busy" @click="toggle(u)">{{u.active?'停用账号':'重新启用'}}</button></div></article><p class="muted" style="margin-top:15px">停用会立即撤销该用户的登录会话，保留其资料与方案。</p></section></div><section v-else class="panel"><h2>你的个人空间</h2><p>从顶部导航进入知识库、MCP 工具和约会规划。普通账号仅可使用允许的知识检索、时间查询及 PDF 工具。</p><p class="muted" style="margin-top:16px">需要邀请其他人加入时，请联系管理员。</p></section></div></WorkspaceLayout></template>
